#pragma once

#include <string>

namespace clockcore
{

// One selectable time zone of the on-clock menu.
struct TzEntry
{
    const char* name;  // IANA name, e.g. "Europe/Prague"
    const char* posix; // POSIX TZ rule incl. DST, e.g. "CET-1CEST,M3.5.0,M10.5.0/3"
};

// Curated zone list (generated by scripts/gen_tz_table.py).
const TzEntry* tzTable();
int tzTableSize();

// Index of the zone with the given IANA name, or -1.
int tzIndexOf(const std::string& name);

} // namespace clockcore
